import {sources} from './grid-queues-scenes.js';
import {ercotSnapshot,dominionSnapshot,projectOptions,securityFaceAmount,stagedLoad} from './grid-queues-model.js';
const credit=(label,url)=>`<p class="q-credit"><a href="${url}" target="_blank" rel="noreferrer">${label}</a></p>`;
const arrow='<span class="q-arrow" aria-hidden="true">→</span>';
const rack='<span class="q-rack" aria-hidden="true"><i></i><i></i><i></i><i></i></span>';
const figure=(file,alt,label,url)=>`<figure class="q-source-figure"><a class="full-size-figure" href="../assets/references/${file}" target="_blank" rel="noopener" aria-label="Open full-size source figure"><img src="../assets/references/${file}" alt="${alt}"></a><figcaption>${credit(label,url)}</figcaption></figure>`;
function options(state){
 const chosen=state.siteChoice==='selected',m=projectOptions(chosen);
 return `<div class="q-options"><div class="q-project"><span>One planned deployment</span><strong>1 GW</strong></div><div class="q-site-branches" aria-hidden="true"></div><div class="q-sites">${['A','B','C'].map(id=>`<section class="${m.activeSites.includes(id)?'active':'withdrawn'}"><h2>Site ${id}</h2>${rack}<strong>${m.activeSites.includes(id)?'1 GW request':'Withdrawn'}</strong></section>`).join('')}</div><p class="q-option-total"><strong>${m.requestedMW/1000} GW</strong> of active requests <span>·</span> <strong>1 GW</strong> planned campus</p></div>`;
}
function pipeline(){
 const m=ercotSnapshot;
 return `<div class="q-stack"><p class="q-dateline">June 2026 snapshot · requested ramps through 2033</p><div class="q-bars">${[[m.totalGW,'Tracked large-load pipeline','total'],[m.noStudiesGW,'No studies submitted','pending'],[m.observedGW,'Observed energized','live']].map(([value,label,cls])=>`<section class="q-bar-row ${cls}"><div><span>${label}</span><strong>${value} GW</strong></div><div class="q-bar-track"><span style="width:${value/m.totalGW*100}%"></span></div></section>`).join('')}</div><p class="q-definition">“Observed” counts non-simultaneous historical peaks.</p>${credit('ERCOT · July 29, 2026 · selected status categories',sources.ercot)}</div>`;
}
function commitments(){return `<div class="q-stack"><div class="q-two q-money"><section><span class="q-kicker">Screening study</span><strong>$100,000</strong><p>Study fee</p></section><section><span class="q-kicker">Intermediate agreement</span><strong>$50,000 / MW</strong><p>Financial security</p></section></div><div class="q-security-example"><span>1 GW request</span>${arrow}<strong>$${securityFaceAmount(1000)/1e6} million</strong><span>security face amount</span></div>${credit('Texas rule adopted September 18 · effective October 8, 2026',sources.security)}</div>`;}
function dominion(){
 const m=dominionSnapshot;
 return `<div class="q-stack"><div class="q-dom-total"><strong>${m.totalGW} GW</strong><span>Agreements · July 2025</span></div><div class="q-contract-mix" role="img" aria-label="47 GW agreements: 30.1 GW engineering, 7.1 GW construction and 9.8 GW service"><span class="engineering" style="flex:${m.engineeringGW}"></span><span class="construction" style="flex:${m.constructionGW}"></span><span class="service" style="flex:${m.serviceGW}"></span></div><div class="q-contract-legend"><span class="engineering"><b>30.1 GW</b>Engineering</span><span class="construction"><b>7.1 GW</b>Construction</span><span class="service"><b>9.8 GW</b>Service</span></div><div class="q-observed"><strong>${m.coincidentPeakGW} GW</strong><span>Coincident data-center peak · 2025</span></div>${credit('Dominion Energy customer portfolio · filing January 6, 2026',sources.dominion)}</div>`;
}
export function gridQueuesVisual(id,state={}){
 switch(id){
 case 'queue-purpose':return `<div class="q-opening"><div class="q-regions"><section><span class="q-region-mark">TX</span><h2>ERCOT</h2><p>Most of Texas</p></section><span class="q-region-divider" aria-hidden="true"></span><section><span class="q-region-mark">PJM</span><h2>PJM</h2><p>Multi-state eastern grid</p></section></div><p class="q-opening-line">A request for power. A commitment to build. Electricity at the meter.</p><p class="q-dateline">Case studies · evidence checked September 20, 2026</p></div>`;
 case 'two-queues':return `<div class="q-stack"><div class="q-grid-path"><section class="q-end supply"><span class="q-kicker">Supply connection</span><h2>New generation</h2><span class="q-power-icon" aria-hidden="true">⚡</span><p>Inject power</p></section>${arrow}<section class="q-network"><div class="q-mesh" aria-hidden="true"><i></i><i></i><i></i><i></i></div><h2>The grid</h2></section>${arrow}<section class="q-end demand"><span class="q-kicker">Load connection</span><h2>Data center</h2>${rack}<p>Withdraw power</p></section></div><div class="q-supply-fact"><strong>PJM: 201.5 GW</strong><span>Generation nameplate accepted for study · August 2026</span></div>${credit('PJM Cycle 1 · FERC large-load proceeding',sources.pjmSupply)}</div>`;
 case 'ercot-pipeline':return pipeline();
 case 'site-options':return options(state);
 case 'ercot-analyst':return figure('grid-queues-sa-requests.png','SemiAnalysis compares 410 GW total ERCOT requests, including 357 GW data centers in April 2026, with its 45.4 GW tracked data-center buildout through fourth quarter 2030. Phantom and duplicative classification is the publisher’s estimate.','SemiAnalysis · June 18, 2026 · analyst model comparison',sources.saRequests);
 case 'commitment-costs':return commitments();
 case 'batch-zero':return `<div class="q-stack"><div class="q-batch-stat"><strong>≈205 GW</strong><span>Preliminarily eligible · July 28, 2026</span></div><div class="q-gates"><section><b>Eligible</b><span>Enter the process</span></section>${arrow}<section class="current"><b>Verify</b><span>Evidence behind the request</span></section>${arrow}<section><b>Study</b><span>Applicable engineering work</span></section>${arrow}<section><b>Energize</b><span>Separate approval</span></section></div><p class="q-definition">September 9: verification requests still underway.</p>${credit('ERCOT · July 28 eligibility snapshot',sources.batch)+credit('ERCOT · September 9 verification notice',sources.verification)}</div>`;
 case 'dominion-contracts':return `<div class="q-stack"><div class="q-contracts"><section><span class="q-stage">01 · ELOA</span><h2>Engineering</h2><strong>$250,000 deposit</strong><p>Study the connection</p><small>Typically 9–12 months</small></section><section><span class="q-stage">02 · CLOA</span><h2>Construction</h2><strong>Reserve capacity</strong><p>Commit to the work</p><small>Cancellation obligations</small></section><section><span class="q-stage">03 · ESA</span><h2>Electric service</h2><strong>Contract the service</strong><p>Define capacity and collateral</p><small>Required before service</small></section></div>${credit('Dominion’s process in PJM · January 6, 2026 filing',sources.dominion)}</div>`;
 case 'dominion-demand':return dominion();
 case 'forecast-filter':return figure('grid-queues-sa-forecast.png','Historical ERCOT 2025 system forecast: the 2030 submitted load is 208 GW and the adjusted forecast is 138 GW. This is the whole-system forecast, not a data-center-only queue.','ERCOT 2025 forecast · reproduced by SemiAnalysis, March 3, 2026',sources.saForecast);
 case 'staged-connection':return `<div class="q-stack"><p class="q-staged-intro">1,000 MW campus · grid import limited to 100 MW</p><div class="q-stages">${[0,1,2].map(n=>`<section><h2>${['No generators ready','One generator ready','Both generators ready'][n]}</h2><div class="q-grid-limit">Grid limit: 100 MW</div><div class="q-generation" aria-label="${n} generators available">${[0,1].map(i=>`<span class="${i<n?'on':'off'}" aria-hidden="true">∿</span>`).join('')}</div><small>Local capacity: ${n*500} MW</small><strong class="q-stage-output">${stagedLoad(n).toLocaleString('en-US')} MW</strong><small>Maximum load</small></section>`).join('')}</div><p class="q-definition">A generator trip does not raise the grid import limit.</p>${credit('Adapted from ERCOT’s May 2026 workshop illustration via SemiAnalysis',sources.saStaged)}</div>`;
 case 'connection-terms':return `<div class="q-close"><div class="q-service"><span>“1 GW campus”</span><strong>What can it actually import?</strong></div><div class="q-terms"><section><b>MW + ramp</b><span>How much, and when?</span></section><section><b>Required works</b><span>Who builds and pays?</span></section><section><b>Operating conditions</b><span>What happens in a shortfall?</span></section></div></div>`;
 default:throw new Error(`Unknown grid queue scene: ${id}`);
 }
}
